(244133, 15915, 6893, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2003-03-24 04:47:48.000000', NULL, 1),
(244134, 15765, 6893, '<td valign="top">This is a great shot of sand, hour glass and light.  Superb!</td>', 'This is a great shot of sand, hour glass and light.  Superb!', '2003-03-24 04:49:05.000000', NULL, 1),
