(244137, 15768, 6893, '<td valign="top">Very fine quality and composition.  I feel it fits the challenge very well.  Great.</td>', 'Very fine quality and composition.  I feel it fits the challenge very well.  Great.', '2003-03-24 05:00:21.000000', NULL, 1),
