(244456, 15838, 4767, '<td valign="top">Yeah, but is the date right?  (Or only once a month?)</td>', 'Yeah, but is the date right?  (Or only once a month?)', '2003-03-24 10:56:43.000000', NULL, 1),
(244460, 15885, 641, '<td valign="top">Great dof, and composition!</td>', 'Great dof, and composition!', '2003-03-24 10:58:30.000000', NULL, 1),
