(244502, 15523, 5728, '<td valign="top">I can''t find anything to critisize about this, for me it''s perfect - 10.</td>', 'I can''t find anything to critisize about this, for me it''s perfect - 10.', '2003-03-24 11:24:07.000000', NULL, 1),
