(244509, 15650, 5728, '<td valign="top">Wonderful use of natural lighting and shadows. The resulting image is perfect - 10.</td>', 'Wonderful use of natural lighting and shadows. The resulting image is perfect - 10.', '2003-03-24 11:27:30.000000', NULL, 1),
(244511, 15881, 4767, '<td valign="top">Or could it be called "Hang Time''?</td>', 'Or could it be called "Hang Time''?', '2003-03-24 11:28:20.000000', NULL, 1),
(244513, 15778, 7364, '<td valign="top">woosh, just like deadlines!</td>', 'woosh, just like deadlines!', '2003-03-24 11:28:38.000000', NULL, 1),
(244514, 15463, 6008, '<td valign="top">This is a cute, original interpretation of the challenge. The composition is good, and the colors go well together. The only criticism I have is very small, and that is I would have liked the numbers on the napkins to be a little stronger, perhaps in black rather than silver.</td>', 'This is a cute, original interpretation of the challenge. The composition is good, and the colors go well together. The only criticism I have is very small, and that is I would have liked the numbers on the napkins to be a little stronger, perhaps in black rather than silver.', '2003-03-24 11:28:47.000000', NULL, 1),
(244515, 15946, 5728, '<td valign="top">The detail here is amazing! Great DOF - 10.</td>', 'The detail here is amazing! Great DOF - 10.', '2003-03-24 11:28:48.000000', NULL, 1),
(244516, 15103, 5728, '<td valign="top">Excellent! What more can I say? - 10.</td>', 'Excellent! What more can I say? - 10.', '2003-03-24 11:29:11.000000', NULL, 1),
(244517, 15685, 5728, '<td valign="top">I love this photo, the reflections of the sunset and cactuses works! - 10.</td>', 'I love this photo, the reflections of the sunset and cactuses works! - 10.', '2003-03-24 11:29:50.000000', NULL, 1),
(244518, 15768, 5728, '<td valign="top">This photo puts me back in time. Good job it is very well composed - 10.</td>', 'This photo puts me back in time. Good job it is very well composed - 10.', '2003-03-24 11:30:35.000000', NULL, 1),
(244519, 15831, 7364, '<td valign="top">Were the any flowers harmed in the making of this photograph?</td>', 'Were the any flowers harmed in the making of this photograph?', '2003-03-24 11:30:54.000000', NULL, 1),
