(244530, 15779, 6008, '<td valign="top">The line of green at the bottom adds a nice contrast, as well as some color to the image. The building is clearly ravaged by time, the crop is good, and the border compliments it well.</td>', 'The line of green at the bottom adds a nice contrast, as well as some color to the image. The building is clearly ravaged by time, the crop is good, and the border compliments it well.', '2003-03-24 11:42:16.000000', NULL, 1),
(244532, 15483, 4767, '<td valign="top">Interesting that the minute hand moves, but the second hand is frozen...  Very graphic image.  I liked it, despite my quibble over which hand is moving.</td>', 'Interesting that the minute hand moves, but the second hand is frozen...  Very graphic image.  I liked it, despite my quibble over which hand is moving.', '2003-03-24 11:44:52.000000', NULL, 1),
(244534, 15695, 4767, '<td valign="top">nice composition and exposure!</td>', 'nice composition and exposure!', '2003-03-24 11:46:08.000000', NULL, 1),
