(245059, 15902, 117, '<td valign="top">nice grain and contrast I like this one</td>', 'nice grain and contrast I like this one', '2003-03-24 18:19:20.000000', NULL, 1),
(245070, 15748, 4366, '<td valign="top">Is your clock running? Better go catch it! This has the absolute best composition I have ever seen! I am intrested in seeing how you took this photograph, did you use a mirror or glass? ... 10</td>', 'Is your clock running? Better go catch it! This has the absolute best composition I have ever seen! I am intrested in seeing how you took this photograph, did you use a mirror or glass? ... 10', '2003-03-24 18:30:00.000000', NULL, 1),
