(245085, 15957, 7385, '<td valign="top">Obviously a setup, but a good picture all the same.</td>', 'Obviously a setup, but a good picture all the same.', '2003-03-24 18:49:33.000000', NULL, 1),
(245086, 15617, 117, '<td valign="top">little bright on the left side-need more focus-maybe a longer shutter speed and different lighting would have worked better</td>', 'little bright on the left side-need more focus-maybe a longer shutter speed and different lighting would have worked better', '2003-03-24 18:51:07.000000', NULL, 1),
(245091, 15888, 6600, '<td valign="top">I really like the way you colored your photo to create the antique look to go with your subject.  Nicely done!</td>', 'I really like the way you colored your photo to create the antique look to go with your subject.  Nicely done!', '2003-03-24 19:00:23.000000', NULL, 1),
(245094, 15535, 7385, '<td valign="top">Nice definition on the flower.  Gotta love the Latin.  Nice first submission, the general.</td>', 'Nice definition on the flower.  Gotta love the Latin.  Nice first submission, the general.', '2003-03-24 19:09:26.000000', NULL, 1),
(245095, 15823, 7385, '<td valign="top">What time?<br/></td>', 'What time?', '2003-03-24 19:10:27.000000', NULL, 1),
(245099, 15779, 6600, '<td valign="top">This is certainly a interesting shot!  This reminds me of the house in the original H.G. Wells ''Time Machine'' movie.  Very nice!</td>', 'This is certainly a interesting shot!  This reminds me of the house in the original H.G. Wells ''Time Machine'' movie.  Very nice!', '2003-03-24 19:17:00.000000', NULL, 1),
(245100, 15811, 6504, '<td valign="top">Very clear, sharp, perfect composition.  Very good photography!</td>', 'Very clear, sharp, perfect composition.  Very good photography!', '2003-03-24 19:19:12.000000', NULL, 1),
(245101, 15875, 6504, '<td valign="top">Original. Good sharp image.</td>', 'Original. Good sharp image.', '2003-03-24 19:21:03.000000', NULL, 1),
(245102, 15550, 6504, '<td valign="top">You got this shot just in the nick of time.   Bet he didn''t know he was about to be entered into a contest.</td>', 'You got this shot just in the nick of time.   Bet he didn''t know he was about to be entered into a contest.', '2003-03-24 19:24:13.000000', NULL, 1),
(245104, 15839, 6504, '<td valign="top">Great idea.  Good and clear.</td>', 'Great idea.  Good and clear.', '2003-03-24 19:26:02.000000', NULL, 1),
(245108, 15774, 6600, '<td valign="top">I really like the ''parking meter'' idea, but I think waiting for brighter day and finding a more as aesthetically pleasing meter would have produced nicer results.  I find this a bit on the dark side (could be my monitor though).</td>', 'I really like the ''parking meter'' idea, but I think waiting for brighter day and finding a more as aesthetically pleasing meter would have produced nicer results.  I find this a bit on the dark side (could be my monitor though).', '2003-03-24 19:28:20.000000', NULL, 1),
(245109, 15830, 6504, '<td valign="top">Nice and clear, Very good lighting, good compostion.  High mark from me!</td>', 'Nice and clear, Very good lighting, good compostion.  High mark from me!', '2003-03-24 19:31:04.000000', NULL, 1),
(245110, 15768, 6504, '<td valign="top">I love this photo.  It truly is another time!  I give this one a high mark</td>', 'I love this photo.  It truly is another time!  I give this one a high mark', '2003-03-24 19:31:37.000000', NULL, 1),
(245115, 15891, 6600, '<td valign="top">Very cool idea and implementation. Like the lighting and composition as well.</td>', 'Very cool idea and implementation. Like the lighting and composition as well.', '2003-03-24 19:36:40.000000', NULL, 1),
(245117, 15103, 5792, '<td valign="top">Looks more like 20 minutes to midnight to me. Nice image. Balck background works for highlighting the neon timepiece. Two nice primary colors. Border matches blue of the sign. Well done.</td>', 'Looks more like 20 minutes to midnight to me. Nice image. Balck background works for highlighting the neon timepiece. Two nice primary colors. Border matches blue of the sign. Well done.', '2003-03-24 19:42:35.000000', NULL, 1),
(245121, 15911, 5792, '<td valign="top">Great composition on a B&amp;W stonework image. 1891 meets the challenge wonderfully.</td>', 'Great composition on a B&W stonework image. 1891 meets the challenge wonderfully.', '2003-03-24 19:46:16.000000', NULL, 1),
(245122, 15331, 6532, '<td valign="top">I tried to do something very similiar and I see you had the same issue I did - a reflection of yourself in the subject....Nice try.  Left side also seems to be cut off or blacked out - subject appears to be standing on one leg.</td>', 'I tried to do something very similiar and I see you had the same issue I did - a reflection of yourself in the subject....Nice try.  Left side also seems to be cut off or blacked out - subject appears to be standing on one leg.', '2003-03-24 19:47:35.000000', NULL, 1),
(245123, 15650, 5792, '<td valign="top">Nice still life. The shadow on the clock face conveys the passage of time in a subtle way. Good light angle.</td>', 'Nice still life. The shadow on the clock face conveys the passage of time in a subtle way. Good light angle.', '2003-03-24 19:48:12.000000', NULL, 1),
(245124, 15930, 6600, '<td valign="top">Nice idea (and departure from the clocks).  I expect that a ''passing along'' to the next generation is being insinuated.  I think a grayscale/desaturated version of this might have been interesting touch as well.  Good job!</td>', 'Nice idea (and departure from the clocks).  I expect that a ''passing along'' to the next generation is being insinuated.  I think a grayscale/desaturated version of this might have been interesting touch as well.  Good job!', '2003-03-24 19:48:32.000000', NULL, 1),
(245126, 15774, 5792, '<td valign="top">A little dark, but nicely done and a good concept.</td>', 'A little dark, but nicely done and a good concept.', '2003-03-24 19:49:30.000000', NULL, 1),
(245127, 15946, 6532, '<td valign="top">Nice</td>', 'Nice', '2003-03-24 19:49:31.000000', NULL, 1),
(245128, 15868, 6532, '<td valign="top">Nice dof</td>', 'Nice dof', '2003-03-24 19:49:59.000000', NULL, 1),
(245129, 15856, 5792, '<td valign="top">You are buffaloing me, I don''t think he''s really asleep. :)</td>', 'You are buffaloing me, I don''t think he''s really asleep. :)', '2003-03-24 19:51:36.000000', NULL, 1),
(245131, 15940, 6600, '<td valign="top">I like the idea and the departure from ''clocks''....  I don''t (personally) care for the extreme graininess in the shot though.</td>', 'I like the idea and the departure from ''clocks''....  I don''t (personally) care for the extreme graininess in the shot though.', '2003-03-24 19:54:41.000000', NULL, 1),
