(245135, 15523, 5792, '<td valign="top">I really like this image, especially the duotone, but I''d sure like to know the f/stop and shutter speed used for it.  It would affect how I rate it.</td>', 'I really like this image, especially the duotone, but I''d sure like to know the f/stop and shutter speed used for it.  It would affect how I rate it.', '2003-03-24 19:58:19.000000', NULL, 1),
(245136, 15946, 6600, '<td valign="top">Very nice composition and color!  Good job. (I questioning myself whether I would have prefered the entire image in focus?)</td>', 'Very nice composition and color!  Good job. (I questioning myself whether I would have prefered the entire image in focus?)', '2003-03-24 19:58:51.000000', NULL, 1),
(245137, 15913, 6532, '<td valign="top">Feels like it is chopped off at the top.</td>', 'Feels like it is chopped off at the top.', '2003-03-24 19:59:39.000000', NULL, 1),
(245139, 15851, 6532, '<td valign="top">I think the building is the focus - if it is I think it should be in focus and not the foreground.</td>', 'I think the building is the focus - if it is I think it should be in focus and not the foreground.', '2003-03-24 20:01:53.000000', NULL, 1),
