(245625, 15775, 5792, '<td valign="top">I like this concept and the idea of time is uniquely met with this image. Good color.<br/> <br/>I might have tried shooting at the highest f/stop I could and focus just in front of the 3 minute bottle (if you can) to get enough depth of field to read the label on the last bottle. People are funny about depth of field here and maybe like it better the way you did it.</td>', 'I like this concept and the idea of time is uniquely met with this image. Good color. I might have tried shooting at the highest f/stop I could and focus just in front of the 3 minute bottle (if you can) to get enough depth of field to read the label on the last bottle. People are funny about depth of field here and maybe like it better the way you did it.', '2003-03-25 04:10:08.000000', NULL, 1),
(245626, 15725, 4517, '<td valign="top">I find the street light a little distracting but it certainly meets the challenge.</td>', 'I find the street light a little distracting but it certainly meets the challenge.', '2003-03-25 04:10:48.000000', NULL, 1),
(245627, 15693, 4517, '<td valign="top">Lots of horrible reflections on the glass and it`s not very straight but it does meet the challenge.</td>', 'Lots of horrible reflections on the glass and it`s not very straight but it does meet the challenge.', '2003-03-25 04:13:16.000000', NULL, 1),
(245628, 15005, 4517, '<td valign="top">Lighting looks a bit harsh but meets the challenge well</td>', 'Lighting looks a bit harsh but meets the challenge well', '2003-03-25 04:14:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(245630, 15831, 7528, '<td valign="top">idea was good but the composition was poor.. sorry..</td>', 'idea was good but the composition was poor.. sorry..', '2003-03-25 04:15:35.000000', NULL, 1),
(245633, 15774, 7528, '<td valign="top">composition can be improved. maybe a tighter crop.<br/>idea is good.</td>', 'composition can be improved. maybe a tighter crop.idea is good.', '2003-03-25 04:23:58.000000', NULL, 1),
(245634, 15685, 5792, '<td valign="top">Maybe it is the reflection of the desert sunset and what appears to be a scrabble board in the clockface, but I realy like this image. It has an interesting combination of color and good clock clarity</td>', 'Maybe it is the reflection of the desert sunset and what appears to be a scrabble board in the clockface, but I realy like this image. It has an interesting combination of color and good clock clarity', '2003-03-25 04:24:56.000000', NULL, 1),
(245635, 15866, 7528, '<td valign="top">i really like the composition but not the most original idea. <br/>could be sharper..</td>', 'i really like the composition but not the most original idea. could be sharper..', '2003-03-25 04:25:50.000000', NULL, 1),
(245636, 15768, 5792, '<td valign="top">Good composition, color and texture. An outstanding image.</td>', 'Good composition, color and texture. An outstanding image.', '2003-03-25 04:26:56.000000', NULL, 1),
(245637, 15915, 7528, '<td valign="top">strong composition..  manip?</td>', 'strong composition..  manip?', '2003-03-25 04:29:50.000000', NULL, 1),
(245638, 15800, 5792, '<td valign="top">It is hard to quantify what makes this an exceptional image. A white background with a transparent looking clock is an inspired idea. Very well composed. You are to be commended.</td>', 'It is hard to quantify what makes this an exceptional image. A white background with a transparent looking clock is an inspired idea. Very well composed. You are to be commended.', '2003-03-25 04:30:25.000000', NULL, 1),
(245639, 15779, 5792, '<td valign="top">What an outstanding way to convey a sense of time. One of my favorites this week. I probably would have cropped the green off the bottom to magnify the effect of the dead vines, but that might just be me.</td>', 'What an outstanding way to convey a sense of time. One of my favorites this week. I probably would have cropped the green off the bottom to magnify the effect of the dead vines, but that might just be me.', '2003-03-25 04:34:31.000000', NULL, 1),
(245640, 15842, 5792, '<td valign="top">Meets the challenge exceptionally well. Images with a dominant primary color always appeal to me.</td>', 'Meets the challenge exceptionally well. Images with a dominant primary color always appeal to me.', '2003-03-25 04:36:01.000000', NULL, 1),
(245641, 15677, 5792, '<td valign="top">This image conveys a sense of time very nicely. The brown tones makes it a good color image and it has good clarity.</td>', 'This image conveys a sense of time very nicely. The brown tones makes it a good color image and it has good clarity.', '2003-03-25 04:38:05.000000', NULL, 1),
(245642, 15950, 5792, '<td valign="top">Generally speaking the "Spring Time" images were unappealing. This one is the exception. Well composed. Nice job.</td>', 'Generally speaking the "Spring Time" images were unappealing. This one is the exception. Well composed. Nice job.', '2003-03-25 04:40:40.000000', NULL, 1),
(245644, 15869, 5792, '<td valign="top">This image conveys a sense of time several ways. The old wagon is an interesting photographic subject in and of itself. Starbucks and mini-mall in the background certainly conveys a "then and now" feeling. Taking a daylight time exposure to capture automobile movement is a nice touch.</td>', 'This image conveys a sense of time several ways. The old wagon is an interesting photographic subject in and of itself. Starbucks and mini-mall in the background certainly conveys a "then and now" feeling. Taking a daylight time exposure to capture automobile movement is a nice touch.', '2003-03-25 04:46:10.000000', NULL, 1),
(245645, 15511, 5792, '<td valign="top">Exceptionally well framed. Nice capture of the movement of the hands and good image clarity</td>', 'Exceptionally well framed. Nice capture of the movement of the hands and good image clarity', '2003-03-25 04:48:28.000000', NULL, 1),
(245646, 15936, 7528, '<td valign="top">i think focusing on the memorial itself would have been a better choice.. <br/>idea is good but composition needs improvement.. sorry</td>', 'i think focusing on the memorial itself would have been a better choice.. idea is good but composition needs improvement.. sorry', '2003-03-25 04:49:53.000000', NULL, 1),
(245647, 15959, 5792, '<td valign="top">You captured the movement of the metronome exceptionally well. Very well composed.</td>', 'You captured the movement of the metronome exceptionally well. Very well composed.', '2003-03-25 04:50:51.000000', NULL, 1),
(245650, 15779, 7528, '<td valign="top">like a fairy tale..</td>', 'like a fairy tale..', '2003-03-25 04:53:43.000000', NULL, 1),
(245651, 15643, 5792, '<td valign="top">You see very few pocket watches at airports these days, but people everywhere have went through the trama of being late to the airport countless times. Good concept.</td>', 'You see very few pocket watches at airports these days, but people everywhere have went through the trama of being late to the airport countless times. Good concept.', '2003-03-25 04:55:03.000000', NULL, 1),
(245653, 15536, 5792, '<td valign="top">Nice sepia.</td>', 'Nice sepia.', '2003-03-25 04:56:26.000000', NULL, 1),
(245655, 15931, 5792, '<td valign="top">And I thought I was the only person that used a cell phone as a watch! Nice color and interesting composition.  Good concept for this challenge</td>', 'And I thought I was the only person that used a cell phone as a watch! Nice color and interesting composition.  Good concept for this challenge', '2003-03-25 04:58:47.000000', NULL, 1),
(245656, 15830, 5792, '<td valign="top">Exceptionally well composed image. Light sepia works well in this situation.</td>', 'Exceptionally well composed image. Light sepia works well in this situation.', '2003-03-25 05:00:22.000000', NULL, 1),
(245658, 15696, 5792, '<td valign="top">Very eye catching image. Too bad that distracting cable or whatever it is hanging from the lamp post is there. You could see sunspots if there were any there right now.</td>', 'Very eye catching image. Too bad that distracting cable or whatever it is hanging from the lamp post is there. You could see sunspots if there were any there right now.', '2003-03-25 05:02:50.000000', NULL, 1),
(245659, 15845, 5792, '<td valign="top">I haven''t decided if I would like more contrast here, but I like the blue color and composition of this image.</td>', 'I haven''t decided if I would like more contrast here, but I like the blue color and composition of this image.', '2003-03-25 05:04:23.000000', NULL, 1),
(245661, 15955, 5792, '<td valign="top">Beautiful with the blue background against the gold watch.</td>', 'Beautiful with the blue background against the gold watch.', '2003-03-25 05:05:12.000000', NULL, 1),
(245662, 15760, 6349, '<td valign="top">not a bad shot, but could use some work in terms of lighting / color balance.  It also seems a bot blurry.  You might have had the camera to close for it to focus well.  It is always better to use a tripod if you can.  The subject itself is good and the angle is fine.  It''s just the lighting and focus that are off.  4</td>', 'not a bad shot, but could use some work in terms of lighting / color balance.  It also seems a bot blurry.  You might have had the camera to close for it to focus well.  It is always better to use a tripod if you can.  The subject itself is good and the angle is fine.  It''s just the lighting and focus that are off.  4', '2003-03-25 05:07:21.000000', NULL, 1),
(245664, 15831, 5792, '<td valign="top">No matter what the challenge is flowers always seem to make an appearance.<br/> <br/>This one, however, meets the challenge exceptionally well and conveys the sense of time dramatically. The textured blue background is outstanding and so are the soft shadows. The flowers are well placed and clarity is exceptional.</td>', 'No matter what the challenge is flowers always seem to make an appearance. This one, however, meets the challenge exceptionally well and conveys the sense of time dramatically. The textured blue background is outstanding and so are the soft shadows. The flowers are well placed and clarity is exceptional.', '2003-03-25 05:10:04.000000', NULL, 1),
(245665, 15109, 7528, '<td valign="top">i think a single b&amp;w portrait would have been better.. close cropping.. <br/></td>', 'i think a single b&w portrait would have been better.. close cropping.. ', '2003-03-25 05:15:24.000000', NULL, 1),
