(245807, 15761, 4008, '<td valign="top">Good light to emphasise the old skin, contrast with the young boy. Good composition, the empty space adds to the picture. It is different and I like it.</td>', 'Good light to emphasise the old skin, contrast with the young boy. Good composition, the empty space adds to the picture. It is different and I like it.', '2003-03-25 11:18:10.000000', NULL, 1),
(245808, 15748, 7357, '<td valign="top">great picture love the subject and where you have it set</td>', 'great picture love the subject and where you have it set', '2003-03-25 11:18:35.000000', NULL, 1),
(245809, 15768, 4008, '<td valign="top">Great composition and light. Nice illustration of time. What a relief in this challenge.</td>', 'Great composition and light. Nice illustration of time. What a relief in this challenge.', '2003-03-25 11:18:58.000000', NULL, 1),
(245810, 15885, 4008, '<td valign="top">Well composed and good use of DOF.</td>', 'Well composed and good use of DOF.', '2003-03-25 11:19:32.000000', NULL, 1),
