(245812, 15765, 4008, '<td valign="top">Unlike many others, you have created an attactive abstract. Good work.</td>', 'Unlike many others, you have created an attactive abstract. Good work.', '2003-03-25 11:20:36.000000', NULL, 1),
(245813, 15891, 4008, '<td valign="top">Others have tried to do the same, but only you have created an appealing image out of it. good composition and light.</td>', 'Others have tried to do the same, but only you have created an appealing image out of it. good composition and light.', '2003-03-25 11:21:29.000000', NULL, 1),
(245815, 15831, 4008, '<td valign="top">Good idea, good image. Would be even better if the orange flower would have been yellow as well, and larger, like the second flower.</td>', 'Good idea, good image. Would be even better if the orange flower would have been yellow as well, and larger, like the second flower.', '2003-03-25 11:23:12.000000', NULL, 1),
(245817, 15662, 4008, '<td valign="top">O.k. it is a picture of a watch like many others, but apparently you know what you are doing. Good background, composition, light. Attractive as a whole.</td>', 'O.k. it is a picture of a watch like many others, but apparently you know what you are doing. Good background, composition, light. Attractive as a whole.', '2003-03-25 11:24:38.000000', NULL, 1),
(245818, 15930, 4008, '<td valign="top">Good idea to use two hands to illustrate age and time, combined with the sand falling. Like it.</td>', 'Good idea to use two hands to illustrate age and time, combined with the sand falling. Like it.', '2003-03-25 11:25:32.000000', NULL, 1),
(245821, 14996, 4008, '<td valign="top">Loverly colors, would have been better if you had waited for two minutes to have the arms stand out more from the background, plus light up the middle more.</td>', 'Loverly colors, would have been better if you had waited for two minutes to have the arms stand out more from the background, plus light up the middle more.', '2003-03-25 11:28:57.000000', NULL, 1),
(245822, 15946, 4008, '<td valign="top">The extremely narrow depth of field adds something special to this image.</td>', 'The extremely narrow depth of field adds something special to this image.', '2003-03-25 11:29:49.000000', NULL, 1),
(245823, 15883, 117, '<td valign="top">need more focus and detail</td>', 'need more focus and detail', '2003-03-25 11:30:22.000000', NULL, 1),
