(245952, 15980, 7033, '<td valign="top">Very good set-up; would have preferred a slightly greater DOF, though, to put at least the hourglass in sharper focus.  Receding focus on the book works very well.</td>', 'Very good set-up; would have preferred a slightly greater DOF, though, to put at least the hourglass in sharper focus.  Receding focus on the book works very well.', '2003-03-25 13:48:53.000000', NULL, 1),
(245960, 15584, 5684, '<td valign="top">Greater contrast would have helped</td>', 'Greater contrast would have helped', '2003-03-25 14:09:06.000000', NULL, 1),
(245967, 15761, 7504, '<td valign="top">I see the man as being in the present and the boy is in the past.  Thus the difference in lighting, the boy is somewhat in shadow but looking forward and the man is looking toward the void, just my interpretation.  I love it!</td>', 'I see the man as being in the present and the boy is in the past.  Thus the difference in lighting, the boy is somewhat in shadow but looking forward and the man is looking toward the void, just my interpretation.  I love it!', '2003-03-25 14:21:23.000000', NULL, 1),
(245968, 15827, 7504, '<td valign="top">I love this one.  The misty sunlight and the beautiful old trees in contrast with the boy.  Very nicely done!</td>', 'I love this one.  The misty sunlight and the beautiful old trees in contrast with the boy.  Very nicely done!', '2003-03-25 14:22:36.000000', NULL, 1),
