(246550, 15883, 7073, '<td valign="top">awesome shot... should back up some and make it more clear!</td>', 'awesome shot... should back up some and make it more clear!', '2003-03-26 08:17:45.000000', NULL, 1),
(246551, 15666, 2978, '<td valign="top">Not depcting time at all for me</td>', 'Not depcting time at all for me', '2003-03-26 08:18:25.000000', NULL, 1),
