(246553, 15511, 2978, '<td valign="top">the hands are too bright</td>', 'the hands are too bright', '2003-03-26 08:19:12.000000', NULL, 1),
(246554, 15103, 6870, '<td valign="top">Wow, written with a flashlight? Very nice, however it was done. The colors on black are wonderful and striking.</td>', 'Wow, written with a flashlight? Very nice, however it was done. The colors on black are wonderful and striking.', '2003-03-26 08:20:04.000000', NULL, 1),
(246556, 15768, 2978, '<td valign="top">Is this in the movie set?</td>', 'Is this in the movie set?', '2003-03-26 08:22:07.000000', NULL, 1),
(246557, 15868, 6870, '<td valign="top">Nice perspective. B/W works for this photo well. I wish the glass and sand were as sharp as the wooden housing. I love the shadows in the back. Nice work.</td>', 'Nice perspective. B/W works for this photo well. I wish the glass and sand were as sharp as the wooden housing. I love the shadows in the back. Nice work.', '2003-03-26 08:22:13.000000', NULL, 1),
(246558, 15523, 6870, '<td valign="top">I love the perspective and tones here, and the light coming from the top works really well for me. I don''t mind the blurry top portion of the photo, but I''m unsure as to why you chose to leave that blurry. Anyway, very nice work!</td>', 'I love the perspective and tones here, and the light coming from the top works really well for me. I don''t mind the blurry top portion of the photo, but I''m unsure as to why you chose to leave that blurry. Anyway, very nice work!', '2003-03-26 08:24:25.000000', NULL, 1),
(246559, 15831, 6870, '<td valign="top">I love flowers, so this is one of my favorites this week. Very creative to show time in this way. Similar to a previous challenge. Sharp focus, great composition and wonderful color make this image engaging and interesting. Very nice work.</td>', 'I love flowers, so this is one of my favorites this week. Very creative to show time in this way. Similar to a previous challenge. Sharp focus, great composition and wonderful color make this image engaging and interesting. Very nice work.', '2003-03-26 08:25:57.000000', NULL, 1),
(246560, 15856, 2978, '<td valign="top">Do they have the sense of time?</td>', 'Do they have the sense of time?', '2003-03-26 08:27:51.000000', NULL, 1),
(246561, 15885, 6870, '<td valign="top">You manage with this image to still capture interesting light, despite it being "candid" in a way, and I like how you suggest specificity in your communication of time. I wish the entire watch and hand were in focus, but I love how the runner is not.</td>', 'You manage with this image to still capture interesting light, despite it being "candid" in a way, and I like how you suggest specificity in your communication of time. I wish the entire watch and hand were in focus, but I love how the runner is not.', '2003-03-26 08:27:58.000000', NULL, 1),
(246563, 15728, 2978, '<td valign="top">The first time I see it.</td>', 'The first time I see it.', '2003-03-26 08:29:24.000000', NULL, 1),
(246564, 15949, 6870, '<td valign="top">You really capture the mystery of the machinery here very well with your fascinating perspective. I like the lighting, too. Just wish every part of the machine were in focus. Digital cameras are famous for not having much DOF, though. Still, really intriguing, engaging image!</td>', 'You really capture the mystery of the machinery here very well with your fascinating perspective. I like the lighting, too. Just wish every part of the machine were in focus. Digital cameras are famous for not having much DOF, though. Still, really intriguing, engaging image!', '2003-03-26 08:29:55.000000', NULL, 1),
(246565, 15584, 2978, '<td valign="top">I don''t see your point. I think the playground in the back is not well composed with the man.</td>', 'I don''t see your point. I think the playground in the back is not well composed with the man.', '2003-03-26 08:31:53.000000', NULL, 1),
(246566, 15308, 6870, '<td valign="top">So many intricate textures and lines, contrasting with the simplicity of the snow. Wish we had more snow this year. It''ll be another drought. The clock is sharp and your perspective works well for me. I kind of wish the whole building were in sharper focus, though. Nice job.</td>', 'So many intricate textures and lines, contrasting with the simplicity of the snow. Wish we had more snow this year. It''ll be another drought. The clock is sharp and your perspective works well for me. I kind of wish the whole building were in sharper focus, though. Nice job.', '2003-03-26 08:33:06.000000', NULL, 1),
(246567, 15876, 2978, '<td valign="top">Another naptime photo.</td>', 'Another naptime photo.', '2003-03-26 08:34:31.000000', NULL, 1),
(246568, 15644, 7438, '<td valign="top">This would''ve worked better on a black floor/backdrop.</td>', 'This would''ve worked better on a black floor/backdrop.', '2003-03-26 08:35:13.000000', NULL, 1),
(246570, 15948, 2978, '<td valign="top">Grain</td>', 'Grain', '2003-03-26 08:37:48.000000', NULL, 1),
(246571, 15915, 2978, '<td valign="top">Wow I saw the very same kind of clock in this challenge before. It''s good but this one is definitely cool. Actually, one of my fave this week so far. I like the way you play with the contrast. And the composition is just perfect. Good luck</td>', 'Wow I saw the very same kind of clock in this challenge before. It''s good but this one is definitely cool. Actually, one of my fave this week so far. I like the way you play with the contrast. And the composition is just perfect. Good luck', '2003-03-26 08:44:41.000000', NULL, 1),
