(247453, 15957, 5792, '<td valign="top">Isn''t it always true that "All-nighter + missed physics test + sleeping student = F"? <br/> <br/>This image, however, should get an A+.<br/> <br/>It is very difficult to tell a whole story with a single picture but this one does. That meets the "time" challenge better than any other image.  The time on the clock MEANS something.<br/> <br/>You know what happened before this moment and you can tell how this obviously anal, Mr. Neatnick student will react after he wakes up. It is something special to accomplish that with just a single image.<br/> <br/>The only small criticism I have is that the bottom of the clock is slightly cut off. If you moved the clock to the right a little "up" closer to the glasses you not only would cure that little problem but you could have something of interest to the viewer at three of four intersection points in the rule of thirds. ("Exam announcement" in lower left, "Clock" in lower right and "sleeping student" in upper right) That would be pretty special!</td>', 'Isn''t it always true that "All-nighter + missed physics test + sleeping student = F"?  This image, however, should get an A+. It is very difficult to tell a whole story with a single picture but this one does. That meets the "time" challenge better than any other image.  The time on the clock MEANS something. You know what happened before this moment and you can tell how this obviously anal, Mr. Neatnick student will react after he wakes up. It is something special to accomplish that with just a single image. The only small criticism I have is that the bottom of the clock is slightly cut off. If you moved the clock to the right a little "up" closer to the glasses you not only would cure that little problem but you could have something of interest to the viewer at three of four intersection points in the rule of thirds. ("Exam announcement" in lower left, "Clock" in lower right and "sleeping student" in upper right) That would be pretty special!', '2003-03-27 19:32:14.000000', NULL, 1),
(247457, 15666, 6870, '<td valign="top">Wide eyed! A striking image, perhaps a bit too striking, and true to the challenge. I find the colors a bit strange; but then again, I''m slightly colorblind. Nice composition with the eye lower.</td>', 'Wide eyed! A striking image, perhaps a bit too striking, and true to the challenge. I find the colors a bit strange; but then again, I''m slightly colorblind. Nice composition with the eye lower.', '2003-03-27 20:33:02.000000', NULL, 1),
(247458, 15977, 6870, '<td valign="top">Even the car is from the past. Nice work. I like this still life a lot. There may be limited color enough to go ahead and make it B/W, but that''s something to experiment with. I like the perspective here, looking thorugh the big wheel and the machinery.</td>', 'Even the car is from the past. Nice work. I like this still life a lot. There may be limited color enough to go ahead and make it B/W, but that''s something to experiment with. I like the perspective here, looking thorugh the big wheel and the machinery.', '2003-03-27 20:35:16.000000', NULL, 1),
(247459, 15919, 6870, '<td valign="top">I enjoy the interesting reflection on the clock here. You may want to crop more to just get that and a little bit more. Hmmm. Just thinking. It''s just that the reflection is the most attention-getting thing in the photo, so I''m wondering why it''s so important. Nice lighting and focus, by the way. I like.</td>', 'I enjoy the interesting reflection on the clock here. You may want to crop more to just get that and a little bit more. Hmmm. Just thinking. It''s just that the reflection is the most attention-getting thing in the photo, so I''m wondering why it''s so important. Nice lighting and focus, by the way. I like.', '2003-03-27 20:37:33.000000', NULL, 1),
(247461, 15535, 6870, '<td valign="top">B/W was an interesting choice here. I''m not sure why it was chosen. The attention is certainly on the daffodil and then falls to the plaque thingy. Since I''m not sure what it is the daffodil rests on, I''m not sure what the photo is trying to do. A clearer connection between subject matter and title may be in order. But I''m probably just stupid not to know what that flower is sitting on!</td>', 'B/W was an interesting choice here. I''m not sure why it was chosen. The attention is certainly on the daffodil and then falls to the plaque thingy. Since I''m not sure what it is the daffodil rests on, I''m not sure what the photo is trying to do. A clearer connection between subject matter and title may be in order. But I''m probably just stupid not to know what that flower is sitting on!', '2003-03-27 20:43:23.000000', NULL, 1),
(247463, 15872, 6870, '<td valign="top">Very nice composition here, and I love how the sun dial rests upon that very interesting stump. I think this photo could use more interesting light. The harshness of the light makes things a bit, well, harsh for me.</td>', 'Very nice composition here, and I love how the sun dial rests upon that very interesting stump. I think this photo could use more interesting light. The harshness of the light makes things a bit, well, harsh for me.', '2003-03-27 20:45:24.000000', NULL, 1),
(247464, 15971, 6870, '<td valign="top">A fun shot. I like how the lines indicate an upward movement of the clock numbers.</td>', 'A fun shot. I like how the lines indicate an upward movement of the clock numbers.', '2003-03-27 20:46:13.000000', NULL, 1),
(247465, 15955, 6870, '<td valign="top">Fitting and appropriate title. I like how you''ve revealed the intricacies of this watch. the light is a bit harsh and uninteresting, but I love the composition and perspective.</td>', 'Fitting and appropriate title. I like how you''ve revealed the intricacies of this watch. the light is a bit harsh and uninteresting, but I love the composition and perspective.', '2003-03-27 20:47:27.000000', NULL, 1),
(247466, 15747, 7190, '<td valign="top">I''m wondering why the progressive loss of focus ? I think you could have accomplished the same theme with manipulation of the light or placement..good idea</td>', 'I''m wondering why the progressive loss of focus ? I think you could have accomplished the same theme with manipulation of the light or placement..good idea', '2003-03-27 20:48:42.000000', NULL, 1),
(247467, 15843, 6870, '<td valign="top">I can''t wait ''til this happens up here! I really enjoy the various lines that criss cross their way behind the subject. I find the light a bit uninteresting, but I love the textures and composition of the flowers in the frame.</td>', 'I can''t wait ''til this happens up here! I really enjoy the various lines that criss cross their way behind the subject. I find the light a bit uninteresting, but I love the textures and composition of the flowers in the frame.', '2003-03-27 20:49:04.000000', NULL, 1),
(247468, 15875, 6870, '<td valign="top">You selected an interesting perspective to reveal the inner workings of this clock. If you had more interesting light, this image would really catch my attention. The light is cold and scientific, and so doesn''t help this image much. I love the composition here. The metal silver band going across leads my eye around and tempts me as to what it is hiding.</td>', 'You selected an interesting perspective to reveal the inner workings of this clock. If you had more interesting light, this image would really catch my attention. The light is cold and scientific, and so doesn''t help this image much. I love the composition here. The metal silver band going across leads my eye around and tempts me as to what it is hiding.', '2003-03-27 20:51:11.000000', NULL, 1),
(247469, 15163, 6870, '<td valign="top">Reminds me of a old, overexposed movie. Though the image may be too bright (I''d like to see more darks), I love the idea and the technique. Soft focus works great for me.</td>', 'Reminds me of a old, overexposed movie. Though the image may be too bright (I''d like to see more darks), I love the idea and the technique. Soft focus works great for me.', '2003-03-27 20:53:01.000000', NULL, 1),
(247470, 15406, 6870, '<td valign="top">Successful motion blur here. I kind of wish you were standing even more still, though. I love the lines and busy-ness of the shot.</td>', 'Successful motion blur here. I kind of wish you were standing even more still, though. I love the lines and busy-ness of the shot.', '2003-03-27 20:54:08.000000', NULL, 1),
(247471, 15747, 6870, '<td valign="top">The receding blur is engaging, but I''m not sure why it''s there. I love the idea of expressing time with this apple. Well composed and interesting image!</td>', 'The receding blur is engaging, but I''m not sure why it''s there. I love the idea of expressing time with this apple. Well composed and interesting image!', '2003-03-27 20:55:31.000000', NULL, 1),
(247473, 15869, 7190, '<td valign="top">liked the concept but too bad it seems so washed out</td>', 'liked the concept but too bad it seems so washed out', '2003-03-27 20:56:24.000000', NULL, 1),
(247475, 15832, 6870, '<td valign="top">Nice lighting and tones. For me, shots like this are difficult to make interesting, but you succeed. I think it is the ever so slight tilt of the text, and the subtle curve of the page?</td>', 'Nice lighting and tones. For me, shots like this are difficult to make interesting, but you succeed. I think it is the ever so slight tilt of the text, and the subtle curve of the page?', '2003-03-27 20:58:13.000000', NULL, 1),
(247476, 15683, 6870, '<td valign="top">Lovely blossoms. The white on white is interesting, but I can\''t help but think that the flowers would stick out so much more had they a darker background. The composition here is outstanding. Simple, direct and engaging.</td>', 'Lovely blossoms. The white on white is interesting, but I can\''t help but think that the flowers would stick out so much more had they a darker background. The composition here is outstanding. Simple, direct and engaging.', '2003-03-27 20:58:49.000000', NULL, 1),
(247477, 15913, 6870, '<td valign="top">This is such a great idea, and you manage to show many different kinds of clocks. I find the light and tone levels a bit uninteresting, and the clocks seem out of focus, but I love the way you subtly contrast the many styles of clocks in your frame.</td>', 'This is such a great idea, and you manage to show many different kinds of clocks. I find the light and tone levels a bit uninteresting, and the clocks seem out of focus, but I love the way you subtly contrast the many styles of clocks in your frame.', '2003-03-27 21:00:25.000000', NULL, 1),
(247478, 15810, 6870, '<td valign="top">Cl;ose up is a super idea for this very interesting clock. The textures are really heightened by your perspective. I find the ghost images of the minute hand really interesting.</td>', 'Cl;ose up is a super idea for this very interesting clock. The textures are really heightened by your perspective. I find the ghost images of the minute hand really interesting.', '2003-03-27 21:01:45.000000', NULL, 1),
(247479, 15857, 6870, '<td valign="top">Wow. Nifty sparkles! I''m not sure what this watch has to do with your title, though. There is no sense of urgency about this image. Rather, it speaks of opulence and intricacy. Lovely to explore.</td>', 'Wow. Nifty sparkles! I''m not sure what this watch has to do with your title, though. There is no sense of urgency about this image. Rather, it speaks of opulence and intricacy. Lovely to explore.', '2003-03-27 21:03:28.000000', NULL, 1),
(247480, 15779, 6870, '<td valign="top">Really intriguing idea and image. More contrast and more interesting light would heighten the mood here, I feel, and give even more attention to the vines and their role in the photo. I like this image a lot.</td>', 'Really intriguing idea and image. More contrast and more interesting light would heighten the mood here, I feel, and give even more attention to the vines and their role in the photo. I like this image a lot.', '2003-03-27 21:04:51.000000', NULL, 1),
(247481, 14996, 6870, '<td valign="top">Spiffy close up with a title that is rather unclimactic (which I like). This image really shows off the intricacy of the clock while not being too busy. Good composition leads to this, as does your skillful use of contrast.</td>', 'Spiffy close up with a title that is rather unclimactic (which I like). This image really shows off the intricacy of the clock while not being too busy. Good composition leads to this, as does your skillful use of contrast.', '2003-03-27 21:06:49.000000', NULL, 1),
(247482, 15893, 6870, '<td valign="top">Clever, punny image. The watch may be a bit overexposed, but the idea here is very clearly communicated.</td>', 'Clever, punny image. The watch may be a bit overexposed, but the idea here is very clearly communicated.', '2003-03-27 21:07:47.000000', NULL, 1),
(247483, 15962, 6870, '<td valign="top">Lovely shot. The negative space at the right makes this work well by giving an implied balance. Skillfully done.</td>', 'Lovely shot. The negative space at the right makes this work well by giving an implied balance. Skillfully done.', '2003-03-27 21:10:16.000000', NULL, 1),
(247484, 15714, 6870, '<td valign="top">I like your use of lines here, and the contrasts make them stick out. I wish there were more engaging light in this scene, though. This may also work well as a B/W image.</td>', 'I like your use of lines here, and the contrasts make them stick out. I wish there were more engaging light in this scene, though. This may also work well as a B/W image.', '2003-03-27 21:12:13.000000', NULL, 1),
(247485, 15187, 6870, '<td valign="top">Tough shot with the sillhouettes and bright window. Evening out the window tones would put the coffee drinkers in more darkness, but the shot may show more balance overall. Relevant for the challenge and for our time. I love this idea and the action you''ve captured in both the foreground and background.</td>', 'Tough shot with the sillhouettes and bright window. Evening out the window tones would put the coffee drinkers in more darkness, but the shot may show more balance overall. Relevant for the challenge and for our time. I love this idea and the action you''ve captured in both the foreground and background.', '2003-03-27 21:14:17.000000', NULL, 1),
(247486, 15642, 6870, '<td valign="top">Nice collection of clocks! The arrangement shows great skill. I find the light a bit harsh and "scientific," but I love the composition and clarity.</td>', 'Nice collection of clocks! The arrangement shows great skill. I find the light a bit harsh and "scientific," but I love the composition and clarity.', '2003-03-27 21:15:48.000000', NULL, 1),
(247489, 15924, 7033, '<td valign="top">Great detail; very nice focus.  Must say it''s a bit cheesy, though :-)</td>', 'Great detail; very nice focus.  Must say it''s a bit cheesy, though :-)', '2003-03-27 21:27:47.000000', NULL, 1),
(247492, 15843, 7033, '<td valign="top">Nice shot!  Colors work quite well.  Overall, might be better with a more shallow DOF (to completely blur the branches in the background), but that may not be possible with your camera (I know it''s not with mine)</td>', 'Nice shot!  Colors work quite well.  Overall, might be better with a more shallow DOF (to completely blur the branches in the background), but that may not be possible with your camera (I know it''s not with mine)', '2003-03-27 21:30:27.000000', NULL, 1),
(247493, 15830, 7033, '<td valign="top">Great shot!  Tonal range and desaturated color really works well with your subject.</td>', 'Great shot!  Tonal range and desaturated color really works well with your subject.', '2003-03-27 21:32:30.000000', NULL, 1),
(247497, 15761, 6597, '<td valign="top">good contrast</td>', 'good contrast', '2003-03-27 21:36:26.000000', NULL, 1),
(247499, 15732, 7033, '<td valign="top">Fantastic shot!  Nice color, very sharp focus; good perspective, and a creative crop (the branches at the top are a nice touch) all come together for a great shot.</td>', 'Fantastic shot!  Nice color, very sharp focus; good perspective, and a creative crop (the branches at the top are a nice touch) all come together for a great shot.', '2003-03-27 21:38:34.000000', NULL, 1),
(247501, 15187, 7033, '<td valign="top">Good use of contrasts; B/W tone is perfect for this shot.</td>', 'Good use of contrasts; B/W tone is perfect for this shot.', '2003-03-27 21:40:12.000000', NULL, 1),
(247503, 15010, 7033, '<td valign="top">Nice idea.  Seems a bit out of focus...</td>', 'Nice idea.  Seems a bit out of focus...', '2003-03-27 21:41:44.000000', NULL, 1),
(247505, 15949, 7033, '<td valign="top">Absolutely beautiful!  Unique perspective really adds to the shot; detail is excellent!  --10</td>', 'Absolutely beautiful!  Unique perspective really adds to the shot; detail is excellent!  --10', '2003-03-27 21:43:06.000000', NULL, 1),
(247509, 15810, 7033, '<td valign="top">Sepia tone and graininess really add to the worn-out appearance of the clock face.  Nicely done!</td>', 'Sepia tone and graininess really add to the worn-out appearance of the clock face.  Nicely done!', '2003-03-27 21:46:21.000000', NULL, 1),
(247514, 15911, 7033, '<td valign="top">Very nice shot!  Desaturation and grain certainly give a feeling of age.</td>', 'Very nice shot!  Desaturation and grain certainly give a feeling of age.', '2003-03-27 21:49:12.000000', NULL, 1),
(247517, 15739, 7033, '<td valign="top">Very interesting shot.  Color adds an almost eerie feeling.</td>', 'Very interesting shot.  Color adds an almost eerie feeling.', '2003-03-27 21:51:24.000000', NULL, 1),
(247518, 15696, 6667, '<td valign="top">To me, this is one of the simplest, yet most dramatic presentation of the "time" passing theme. I like the softness of the colors.  Somewhat of a change from all the other entries. I just wish that wire (or whatever) wasn''t in the way for you.  It detracts from the lean lines. Nice shot.  Good luck.</td>', 'To me, this is one of the simplest, yet most dramatic presentation of the "time" passing theme. I like the softness of the colors.  Somewhat of a change from all the other entries. I just wish that wire (or whatever) wasn''t in the way for you.  It detracts from the lean lines. Nice shot.  Good luck.', '2003-03-27 21:53:07.000000', NULL, 1),
(247519, 15459, 7033, '<td valign="top">Appears to be a bit oversharpened, excessively grainy.</td>', 'Appears to be a bit oversharpened, excessively grainy.', '2003-03-27 21:53:21.000000', NULL, 1),
(247521, 15474, 7033, '<td valign="top">Excellent shot!  Desaturated colors and limited DOF work well.  And although the shot is not level, it is easy to believe that this is the way you intended it.  Very nicely done!</td>', 'Excellent shot!  Desaturated colors and limited DOF work well.  And although the shot is not level, it is easy to believe that this is the way you intended it.  Very nicely done!', '2003-03-27 21:56:01.000000', NULL, 1),
(247522, 15827, 7033, '<td valign="top">Beautiful!  Tonal and contrast range really set the mood.</td>', 'Beautiful!  Tonal and contrast range really set the mood.', '2003-03-27 21:58:29.000000', NULL, 1),
(247523, 15308, 7033, '<td valign="top">Very nicely done!  In my opinion, the shot might benefit a bit if there were another angle that would eliminate the busy background.</td>', 'Very nicely done!  In my opinion, the shot might benefit a bit if there were another angle that would eliminate the busy background.', '2003-03-27 22:00:16.000000', NULL, 1),
(247524, 15483, 7033, '<td valign="top">Incredible shot!  Only comment is that parts of the shot appear to be slightly oversharpened.</td>', 'Incredible shot!  Only comment is that parts of the shot appear to be slightly oversharpened.', '2003-03-27 22:01:58.000000', NULL, 1),
(247525, 15774, 7033, '<td valign="top">Great shot!  Tonal range suits your subject well.</td>', 'Great shot!  Tonal range suits your subject well.', '2003-03-27 22:03:59.000000', NULL, 1),
(247526, 15761, 6325, '<td valign="top">I like the composiiton - leaving the space on the left was good. B&amp;W is done very well. Very good all around.</td>', 'I like the composiiton - leaving the space on the left was good. B&W is done very well. Very good all around.', '2003-03-27 22:04:48.000000', NULL, 1),
(247527, 15831, 6325, '<td valign="top">Unique capturing of the passing of time.</td>', 'Unique capturing of the passing of time.', '2003-03-27 22:05:50.000000', NULL, 1),
(247528, 15768, 6597, '<td valign="top">good idea</td>', 'good idea', '2003-03-27 22:07:16.000000', NULL, 1),
(247529, 15696, 6325, '<td valign="top">Like the composition and the colors. I see the time connection in the closing of another day.</td>', 'Like the composition and the colors. I see the time connection in the closing of another day.', '2003-03-27 22:08:06.000000', NULL, 1),
(247530, 15799, 6597, '<td valign="top">good colors brighten picture up</td>', 'good colors brighten picture up', '2003-03-27 22:08:08.000000', NULL, 1),
(247531, 15831, 7033, '<td valign="top">Great take on the challenge... and a beautiful shot!  Very nicely done!</td>', 'Great take on the challenge... and a beautiful shot!  Very nicely done!', '2003-03-27 22:09:41.000000', NULL, 1),
(247532, 15863, 6325, '<td valign="top">I guess this is frozen time - catching the arm in motion would have been passing time - maybe a better shot. I think you culd have moved in on the subject - no need to show it all.</td>', 'I guess this is frozen time - catching the arm in motion would have been passing time - maybe a better shot. I think you culd have moved in on the subject - no need to show it all.', '2003-03-27 22:10:14.000000', NULL, 1),
(247533, 15643, 7033, '<td valign="top">Very nice composition.  Well done!</td>', 'Very nice composition.  Well done!', '2003-03-27 22:10:59.000000', NULL, 1),
(247534, 15770, 6325, '<td valign="top">I''m trying to be open minded, but ... I guess the deadline was there.</td>', 'I''m trying to be open minded, but ... I guess the deadline was there.', '2003-03-27 22:12:17.000000', NULL, 1),
(247535, 15510, 7033, '<td valign="top">Excellent composition; beautiful colors!</td>', 'Excellent composition; beautiful colors!', '2003-03-27 22:13:49.000000', NULL, 1),
(247536, 15231, 6325, '<td valign="top">HOw long do have to wait until it is ready? Like the colors in the wood contrasting with the zinc straps.</td>', 'HOw long do have to wait until it is ready? Like the colors in the wood contrasting with the zinc straps.', '2003-03-27 22:15:18.000000', NULL, 1),
(247537, 15778, 6325, '<td valign="top">Did it keep in ticking? (Timex commercial from the ''50''s and 60''s for the young crowd.)</td>', 'Did it keep in ticking? (Timex commercial from the ''50''s and 60''s for the young crowd.)', '2003-03-27 22:17:08.000000', NULL, 1),
(247538, 15912, 6325, '<td valign="top">Oh, I finally saw it is a tea kettle (?). Focus should be on the watch.  A larger f# would have helped.</td>', 'Oh, I finally saw it is a tea kettle (?). Focus should be on the watch.  A larger f# would have helped.', '2003-03-27 22:19:20.000000', NULL, 1),
(247541, 15916, 6325, '<td valign="top">Nice image. Love the texture created by the brick work pattern. The tonal range is very narrow. If you use Photoshop, you might try the curves to blacken the upper right and brighten the clock face. I like it - good job.</td>', 'Nice image. Love the texture created by the brick work pattern. The tonal range is very narrow. If you use Photoshop, you might try the curves to blacken the upper right and brighten the clock face. I like it - good job.', '2003-03-27 22:26:13.000000', NULL, 1),
(247543, 15510, 6325, '<td valign="top">I think you need to move in on this shot - all the extra stuff distracts from the subject.</td>', 'I think you need to move in on this shot - all the extra stuff distracts from the subject.', '2003-03-27 22:32:30.000000', NULL, 1),
(247545, 15945, 6325, '<td valign="top">The message was there without the hourglass - it gets in the way.</td>', 'The message was there without the hourglass - it gets in the way.', '2003-03-27 22:36:29.000000', NULL, 1),
(247546, 15774, 6325, '<td valign="top">Good idea for the challenge. Could have been better with more puch in the lighting  - did you try  it with a flash?</td>', 'Good idea for the challenge. Could have been better with more puch in the lighting  - did you try  it with a flash?', '2003-03-27 22:41:08.000000', NULL, 1),
(247547, 15360, 6325, '<td valign="top">Must be in Texas.</td>', 'Must be in Texas.', '2003-03-27 22:42:53.000000', NULL, 1),
(247548, 15667, 6325, '<td valign="top">Nice shot of the water.</td>', 'Nice shot of the water.', '2003-03-27 22:45:41.000000', NULL, 1),
(247554, 15416, 7570, '<td valign="top">nicely captures the "feeling" of time.</td>', 'nicely captures the "feeling" of time.', '2003-03-27 22:54:25.000000', NULL, 1),
(247555, 15643, 6325, '<td valign="top">Focus needs to be more precise to pull this off well.</td>', 'Focus needs to be more precise to pull this off well.', '2003-03-27 23:00:55.000000', NULL, 1),
(247556, 15406, 6597, '<td valign="top">like all the color and the waves</td>', 'like all the color and the waves', '2003-03-27 23:01:18.000000', NULL, 1),
(247558, 15561, 6597, '<td valign="top">good composition the prettiest time picture i''ve seen</td>', 'good composition the prettiest time picture i''ve seen', '2003-03-27 23:02:49.000000', NULL, 1),
(247559, 15948, 6325, '<td valign="top">Good composition and colors.</td>', 'Good composition and colors.', '2003-03-27 23:02:51.000000', NULL, 1),
(247560, 15667, 6597, '<td valign="top">good texture</td>', 'good texture', '2003-03-27 23:03:22.000000', NULL, 1),
(247561, 15946, 6325, '<td valign="top">Like the colors and light. Composed well. Sharper focus on the hands would have been better for me.</td>', 'Like the colors and light. Composed well. Sharper focus on the hands would have been better for me.', '2003-03-27 23:04:00.000000', NULL, 1),
(247563, 14978, 6325, '<td valign="top">Colors are good - like the blue.</td>', 'Colors are good - like the blue.', '2003-03-27 23:07:33.000000', NULL, 1),
(247565, 15573, 6325, '<td valign="top">Nice colors. Good potential. Sharper focus on the yellow beads and snappier lightiing would have lifted the image.</td>', 'Nice colors. Good potential. Sharper focus on the yellow beads and snappier lightiing would have lifted the image.', '2003-03-27 23:11:21.000000', NULL, 1),
(247566, 15728, 6325, '<td valign="top">Is this really Greenwich? Never knew what it looked like.</td>', 'Is this really Greenwich? Never knew what it looked like.', '2003-03-27 23:12:17.000000', NULL, 1),
(247571, 15187, 7491, '<td valign="top">Excellent photograph, great concept! I just looked at this and thought wow!!!!!!<br/>I was floored really. Its great to see  someone use an actual concept and follow through with it with a realistic portrayal.  Anyways.... BRAVO!!!!!!!!<br/>10. I want to see more of your stuff.</td>', 'Excellent photograph, great concept! I just looked at this and thought wow!!!!!!I was floored really. Its great to see  someone use an actual concept and follow through with it with a realistic portrayal.  Anyways.... BRAVO!!!!!!!!10. I want to see more of your stuff.', '2003-03-27 23:33:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(247585, 15642, 1360, '<td valign="top">Beautifully done shot, but it does nothing for me.  It''s somewhat boring. 4.</td>', 'Beautifully done shot, but it does nothing for me.  It''s somewhat boring. 4.', '2003-03-27 23:49:58.000000', NULL, 1),
(247599, 15696, 6803, '<td valign="top">very nice!</td>', 'very nice!', '2003-03-28 00:27:30.000000', NULL, 1),
(247603, 15758, 6480, '<td valign="top">nice idea, the movement looks really cool.</td>', 'nice idea, the movement looks really cool.', '2003-03-28 00:36:48.000000', NULL, 1),
(247604, 15610, 6480, '<td valign="top">i don''t get it</td>', 'i don''t get it', '2003-03-28 00:37:16.000000', NULL, 1),
(247606, 15643, 6480, '<td valign="top">nice idea</td>', 'nice idea', '2003-03-28 00:38:23.000000', NULL, 1),
(247607, 15617, 6480, '<td valign="top">nice idea, but the light in the left corner is a little distracting</td>', 'nice idea, but the light in the left corner is a little distracting', '2003-03-28 00:39:08.000000', NULL, 1),
(247608, 15691, 6480, '<td valign="top">i don''t understand how a flower is supposed to represent morning</td>', 'i don''t understand how a flower is supposed to represent morning', '2003-03-28 00:39:53.000000', NULL, 1),
(247609, 15888, 6480, '<td valign="top">nice photo, but not very creative though</td>', 'nice photo, but not very creative though', '2003-03-28 00:40:56.000000', NULL, 1),
(247610, 15761, 6480, '<td valign="top">good idea, b&amp;w really enchances the photo</td>', 'good idea, b&w really enchances the photo', '2003-03-28 00:41:27.000000', NULL, 1),
(247611, 15552, 6480, '<td valign="top">good idea, but kind of confusing</td>', 'good idea, but kind of confusing', '2003-03-28 00:41:54.000000', NULL, 1),
