INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(250091, 15728, 6064, '<td valign="top">I think a lot of people didn`t "get" this time signal. I should of stuck with the clocks :)</td>', 'I think a lot of people didn`t "get" this time signal. I should of stuck with the clocks :)', '2003-03-31 14:36:46.000000', NULL, 0),
(250516, 15522, 6192, '<td valign="top">On the right track, but you need that extra effort to make your photo stand out from the others.  When I start a challenge I right down all of the cliches and literal interpretations that come to mind.  Then I avoid shooting anything on that list.  It takes more effort, but when the challenge ends 75% of the images people took were on that x-list.<br/>The next most important thing after you have an original subject is light light light, where is it, what is interesting about it, can it be improved, and does it support your subject and the challenge.  Of course there are many more aspects to taking a good photo, but these are two of the most important to me personally.  Good luck, keep at it and you will be surprised how fast you will improve.</td>', 'On the right track, but you need that extra effort to make your photo stand out from the others.  When I start a challenge I right down all of the cliches and literal interpretations that come to mind.  Then I avoid shooting anything on that list.  It takes more effort, but when the challenge ends 75% of the images people took were on that x-list.The next most important thing after you have an original subject is light light light, where is it, what is interesting about it, can it be improved, and does it support your subject and the challenge.  Of course there are many more aspects to taking a good photo, but these are two of the most important to me personally.  Good luck, keep at it and you will be surprised how fast you will improve.', '2003-03-31 17:50:24.000000', NULL, 0),
